const fs = require('node:fs');
const crypto = require('node:crypto');
const dir = 'products/services/contracts-finder-small-data-job';
const source = fs.readFileSync(`${dir}/official-feed.json`);
const sha256 = crypto.createHash('sha256').update(source).digest('hex');
if (sha256 !== '33d85ed3b5e0b38258cf283e4a3481dec45102ba444b62c0f83230a8b3e5b6e0') throw new Error('Official feed hash differs from fetch receipt');
const { releases } = JSON.parse(source);
if (!Array.isArray(releases) || releases.length !== 9) throw new Error('Unexpected capture coverage');
const readback = releases.map(({ id, tag, tender }) => ({ releaseId: id, tag, tenderId: tender?.id, status: tender?.status, title: tender?.title, scope: tender?.description ?? null, lots: (tender?.lots ?? []).map(({ id, title, description }) => ({ id, title, scope: description ?? null })), deadline: tender?.tenderPeriod?.endDate ?? null, awardCriteria: tender?.awardCriteria ?? null, submissionMethod: tender?.submissionMethod ?? null }));
const coverage = { sourceReceipt: 'TASK-179502876101', sha256, window: ['2026-11-17T00:00:00Z', '2026-11-18T00:00:00Z'], releaseCount: releases.length };
const output = `${dir}/pinned-buyer-decision-input.json`;
fs.writeFileSync(output, JSON.stringify({ coverage, readback }, null, 2) + '\n');
const saved = JSON.parse(fs.readFileSync(output, 'utf8'));
if (saved.readback.length !== saved.coverage.releaseCount) throw new Error('Readback count mismatch');
console.log(JSON.stringify({ output, coverage, releasesWithScope: saved.readback.filter(r => r.scope).length, releasesWithLotScope: saved.readback.filter(r => r.lots.some(l => l.scope)).length }));
